{
  "root": "main",
  "state": {
    "itinerary": [
      { "day": "Apr 10", "focus": "Higashiyama temples", "plan": "Kiyomizu-dera, Sannenzaka/Ninenzaka, Gion", "cost": "$180", "icon": "../assets/r_004361_01_3_building.svg" },
      { "day": "Apr 11", "focus": "Arashiyama scenery", "plan": "Bamboo Grove, Tenryu-ji, river views", "cost": "$210", "icon": "../assets/r_004361_01_4_tree.svg" },
      { "day": "Apr 12", "focus": "Central Kyoto food", "plan": "Nishiki Market, temple, free afternoon", "cost": "$160", "icon": "../assets/r_004369_01_1_cup-hot.svg", "image": "../assets/r_004361_01_7_A_store_at_Nishiki_market_2C_Kyoto_2C_Japan.jpg", "imageAlt": "Nishiki Market" },
      { "day": "Apr 13", "focus": "Northern Kyoto", "plan": "Kinkaku-ji, Ryoan-ji, station shopping", "cost": "$170", "icon": "../assets/r_004361_01_6_shop.svg" }
    ],
    "budget": [
      { "category": "Lodging", "amount": "$510" },
      { "category": "Food and drinks", "amount": "$245" },
      { "category": "Local transit", "amount": "$50" },
      { "category": "Temple/admission fees", "amount": "$50" },
      { "category": "Light shopping", "amount": "$120" },
      { "category": "Flex buffer", "amount": "$825" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "itineraryTable", "budgetTable", "actions"]
    },
    "title": { "type": "Text", "props": { "text": "Kyoto Spring Trip Overview", "variant": "h1" }, "children": [] },
    "itineraryTable": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "columns": [
          { "key": "day", "label": "Day" },
          { "key": "focus", "label": "Focus" },
          { "key": "plan", "label": "Plan" },
          { "key": "cost", "label": "Est. Cost" }
        ]
      },
      "children": []
    },
    "budgetTable": {
      "type": "Table",
      "props": {
        "statePath": "/budget",
        "domain": "generic",
        "preferredPresentation": "table",
        "columns": [
          { "key": "category", "label": "Category" },
          { "key": "amount", "label": "Amount" }
        ]
      },
      "children": []
    },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Map Kyoto Route", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.google.com/maps/search/Kyoto+temples+itinerary" } } } }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Check Kyoto Weather", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.timeanddate.com/weather/japan/kyoto" } } } }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Find Trains", "on": { "press": { "action": "openUrl", "params": { "url": "https://www.japan-guide.com/e/e2363.html" } } } }, "children": [] }
  }
}
